using System;
using Framework.AI.Decision;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// Utility AIの評価計算と行動選択を検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class UtilityAITest : MonoBehaviour
    {
        [Header("テスト設定")]
        [SerializeField]
        [Tooltip("開始時にすべてのテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]
        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// 予定されているテスト件数。
        /// </summary>
        private const int ExpectedTestCount = 48;

        /// <summary>
        /// 開始時のテスト実行を制御する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべてのUtility AIテストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            passedCount = 0;
            failedCount = 0;

            try
            {
                TestMath();
                TestConsideration();
                TestOption();
                TestEvaluation();
                TestSelection();
                TestContinuation();
                TestSafety();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }

            Debug.Log(
                $"【UtilityAI テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (failedCount == 0 &&
                 passedCount == ExpectedTestCount
                    ? "すべてのテストに成功しました。"
                    : "失敗または未実行のテストを確認してください。"),
                this);
        }

        /// <summary>
        /// 固定評価値を返すテスト用行動候補を生成する。
        /// </summary>
        /// <param name="id">行動識別子</param>
        /// <param name="score">固定評価値</param>
        /// <returns>生成した行動候補</returns>
        private UtilityOption<string, float> CreateOption(
            string id,
            float score)
        {
            return new UtilityOption<string, float>(
                id,
                new[]
                {
                    new UtilityConsideration<float>(
                        "固定評価", context => score)
                },
                useCompensation: false);
        }

        /// <summary>
        /// 評価値の計算と変換を検証する。
        /// </summary>
        private void TestMath()
        {
            bool clampPassed =
                UtilityMath.Clamp01(-1f) == 0f &&
                UtilityMath.Clamp01(2f) == 1f;
            Debug.Assert(clampPassed, "評価値の範囲制限", this);
            Check(clampPassed, "評価値の範囲制限");

            bool nanPassed =
                UtilityMath.Clamp01(float.NaN) == 0f;
            Debug.Assert(nanPassed, "NaN評価値の安全処理", this);
            Check(nanPassed, "NaN評価値の安全処理");

            bool normalizePassed =
                UtilityMath.Normalize(5f, 0f, 10f) == 0.5f;
            Debug.Assert(normalizePassed, "評価値の正規化", this);
            Check(normalizePassed, "評価値の正規化");

            bool boundaryPassed =
                UtilityMath.Normalize(-1f, 0f, 10f) == 0f &&
                UtilityMath.Normalize(11f, 0f, 10f) == 1f;
            Debug.Assert(boundaryPassed, "正規化の境界条件", this);
            Check(boundaryPassed, "正規化の境界条件");

            bool invertPassed =
                UtilityMath.Invert(0.25f) == 0.75f;
            Debug.Assert(invertPassed, "評価値の反転", this);
            Check(invertPassed, "評価値の反転");

            bool powerPassed =
                Mathf.Approximately(
                    UtilityMath.Power(0.5f, 2f),
                    0.25f);
            Debug.Assert(powerPassed, "べき乗曲線", this);
            Check(powerPassed, "べき乗曲線");

            bool smoothPassed =
                Mathf.Approximately(
                    UtilityMath.SmoothStep(0.25f),
                    0.15625f);
            Debug.Assert(smoothPassed, "S字評価曲線", this);
            Check(smoothPassed, "S字評価曲線");

            bool singlePassed =
                UtilityMath.Compensate(0.5f, 1) == 0.5f;
            Debug.Assert(singlePassed, "単一評価要素の補正", this);
            Check(singlePassed, "単一評価要素の補正");

            bool compensationPassed =
                Mathf.Approximately(
                    UtilityMath.Compensate(0.5f, 2),
                    0.625f);
            Debug.Assert(compensationPassed, "複数評価要素の補正", this);
            Check(compensationPassed, "複数評価要素の補正");

            bool endpointPassed =
                UtilityMath.Compensate(0f, 5) == 0f &&
                UtilityMath.Compensate(1f, 5) == 1f;
            Debug.Assert(endpointPassed, "補正値の境界条件", this);
            Check(endpointPassed, "補正値の境界条件");
        }

        /// <summary>
        /// 個別の評価要素を検証する。
        /// </summary>
        private void TestConsideration()
        {
            var consideration =
                new UtilityConsideration<float>(
                    "攻撃性",
                    context => context);

            bool namePassed =
                consideration.Name == "攻撃性";
            Debug.Assert(namePassed, "評価要素名の保持", this);
            Check(namePassed, "評価要素名の保持");

            bool valuePassed =
                consideration.Evaluate(0.7f) == 0.7f;
            Debug.Assert(valuePassed, "評価処理の実行", this);
            Check(valuePassed, "評価処理の実行");

            bool clampPassed =
                consideration.Evaluate(-2f) == 0f &&
                consideration.Evaluate(2f) == 1f;
            Debug.Assert(clampPassed, "評価要素の範囲制限", this);
            Check(clampPassed, "評価要素の範囲制限");

            bool nanPassed =
                consideration.Evaluate(float.NaN) == 0f;
            Debug.Assert(nanPassed, "不正評価値の安全処理", this);
            Check(nanPassed, "不正評価値の安全処理");

            bool contextPassed =
                consideration.Evaluate(0.2f) == 0.2f &&
                consideration.Evaluate(0.8f) == 0.8f;
            Debug.Assert(contextPassed, "意思決定情報の変更反映", this);
            Check(contextPassed, "意思決定情報の変更反映");
        }

        /// <summary>
        /// 行動候補の評価計算を検証する。
        /// </summary>
        private void TestOption()
        {
            var first =
                new UtilityConsideration<float>(
                    "攻撃性", context => 0.5f);

            var second =
                new UtilityConsideration<float>(
                    "信頼度", context => 0.8f);

            var option =
                new UtilityOption<string, float>(
                    "Chase",
                    new[] { first, second },
                    0.5f,
                    false);

            bool definitionPassed =
                option.Id == "Chase" &&
                option.Weight == 0.5f &&
                option.Considerations.Count == 2 &&
                !option.UseCompensation;
            Debug.Assert(definitionPassed, "行動候補の定義保持", this);
            Check(definitionPassed, "行動候補の定義保持");

            bool productPassed =
                Mathf.Approximately(
                    option.Evaluate(0f), 0.2f);
            Debug.Assert(productPassed, "重み付き乗算評価", this);
            Check(productPassed, "重み付き乗算評価");

            var compensated =
                new UtilityOption<string, float>(
                    "Chase",
                    new[] { first, second });

            bool compensationPassed =
                Mathf.Approximately(
                    compensated.Evaluate(0f), 0.55f);
            Debug.Assert(compensationPassed, "補正付き乗算評価", this);
            Check(compensationPassed, "補正付き乗算評価");

            var empty =
                new UtilityOption<string, float>(
                    "Idle",
                    Array.Empty<UtilityConsideration<float>>(),
                    0.3f);

            bool emptyPassed =
                empty.Evaluate(0f) == 0.3f;
            Debug.Assert(emptyPassed, "評価要素なしの基本重み", this);
            Check(emptyPassed, "評価要素なしの基本重み");

            // 不要な評価処理が実行された回数。
            int queryCount = 0;

            var counter =
                new UtilityConsideration<float>(
                    "呼び出し確認",
                    context =>
                    {
                        queryCount++;

                        return 1f;
                    });

            var unavailable =
                new UtilityOption<string, float>(
                    "Unavailable",
                    new[] { counter },
                    availability: context => false);

            bool unavailablePassed =
                !unavailable.IsAvailable(0f) &&
                unavailable.Evaluate(0f) == 0f &&
                queryCount == 0;
            Debug.Assert(unavailablePassed, "利用不可能な行動の評価省略", this);
            Check(unavailablePassed, "利用不可能な行動の評価省略");

            var zeroWeight =
                new UtilityOption<string, float>(
                    "Disabled",
                    new[] { counter },
                    weight: 0f);

            bool weightPassed =
                zeroWeight.Evaluate(0f) == 0f &&
                queryCount == 0;
            Debug.Assert(weightPassed, "基本重み0の評価省略", this);
            Check(weightPassed, "基本重み0の評価省略");

            var zero =
                new UtilityConsideration<float>(
                    "無効条件", context => 0f);

            var earlyExit =
                new UtilityOption<string, float>(
                    "EarlyExit",
                    new[] { zero, counter });

            bool earlyExitPassed =
                earlyExit.Evaluate(0f) == 0f &&
                queryCount == 0;
            Debug.Assert(earlyExitPassed, "評価値0による早期終了", this);
            Check(earlyExitPassed, "評価値0による早期終了");

            var source =
                new[] { first };

            var copied =
                new UtilityOption<string, float>(
                    "Copied", source);

            source[0] = zero;

            bool copyPassed =
                copied.Evaluate(0f) == 0.5f;
            Debug.Assert(copyPassed, "評価要素コレクションの独立性", this);
            Check(copyPassed, "評価要素コレクションの独立性");
        }

        /// <summary>
        /// 行動評価結果の保持を検証する。
        /// </summary>
        private void TestEvaluation()
        {
            var evaluation =
                new UtilityEvaluation<string>(
                    "Chase", 0.6f, true, 0.1f);

            bool dataPassed =
                evaluation.ActionId == "Chase" &&
                evaluation.RawScore == 0.6f &&
                evaluation.IsCurrentAction &&
                evaluation.IsValid &&
                evaluation.IsSelectable;
            Debug.Assert(dataPassed, "評価結果の情報保持", this);
            Check(dataPassed, "評価結果の情報保持");

            bool bonusPassed =
                Mathf.Approximately(
                    evaluation.SelectionScore, 0.7f);
            Debug.Assert(bonusPassed, "継続優遇値の適用", this);
            Check(bonusPassed, "継続優遇値の適用");

            var other =
                new UtilityEvaluation<string>(
                    "Patrol", 0.6f, false, 0.1f);

            bool otherPassed =
                other.SelectionScore == 0.6f;
            Debug.Assert(otherPassed, "新規行動への優遇抑止", this);
            Check(otherPassed, "新規行動への優遇抑止");

            var invalid =
                new UtilityEvaluation<string>(
                    "Chase", 0f, true, 0.1f);

            bool invalidPassed =
                invalid.SelectionScore == 0f &&
                !invalid.IsSelectable;
            Debug.Assert(invalidPassed, "無効行動への優遇抑止", this);
            Check(invalidPassed, "無効行動への優遇抑止");

            var empty = default(UtilityEvaluation<string>);

            bool defaultPassed =
                !empty.IsValid && !empty.IsSelectable;
            Debug.Assert(defaultPassed, "既定評価結果の無効状態", this);
            Check(defaultPassed, "既定評価結果の無効状態");
        }

        /// <summary>
        /// 行動候補の登録と選択を検証する。
        /// </summary>
        private void TestSelection()
        {
            var selector =
                new UtilitySelector<string, float>();

            bool emptyPassed =
                !selector.TrySelect(0f, out var empty) &&
                !empty.IsValid &&
                selector.Count == 0;
            Debug.Assert(emptyPassed, "行動候補なしの選択失敗", this);
            Check(emptyPassed, "行動候補なしの選択失敗");

            bool addPassed =
                selector.TryAddOption(
                    CreateOption("Chase", 0.8f)) &&
                selector.TryAddOption(
                    CreateOption("Patrol", 0.5f)) &&
                selector.Count == 2 &&
                selector.HasOption("Chase");
            Debug.Assert(addPassed, "行動候補の登録", this);
            Check(addPassed, "行動候補の登録");

            bool duplicatePassed =
                !selector.TryAddOption(
                    CreateOption("Chase", 1f)) &&
                selector.Count == 2;
            Debug.Assert(duplicatePassed, "重複行動IDの拒否", this);
            Check(duplicatePassed, "重複行動IDの拒否");

            bool bestPassed =
                selector.TrySelect(0f, out var selected) &&
                selected.ActionId == "Chase" &&
                selected.RawScore == 0.8f;
            Debug.Assert(bestPassed, "最高評価行動の選択", this);
            Check(bestPassed, "最高評価行動の選択");

            bool historyPassed =
                selector.LastEvaluations.Count == 2 &&
                selector.LastEvaluations[0].ActionId == "Chase" &&
                selector.LastEvaluations[1].ActionId == "Patrol";
            Debug.Assert(historyPassed, "全行動候補の評価結果保持", this);
            Check(historyPassed, "全行動候補の評価結果保持");

            bool removePassed =
                selector.TryRemoveOption("Chase") &&
                !selector.HasOption("Chase") &&
                selector.LastEvaluations.Count == 0 &&
                selector.TrySelect(0f, out var next) &&
                next.ActionId == "Patrol";
            Debug.Assert(removePassed, "行動削除後の再選択", this);
            Check(removePassed, "行動削除後の再選択");

            selector.Clear();

            bool clearPassed =
                selector.Count == 0 &&
                selector.LastEvaluations.Count == 0 &&
                !selector.TrySelect(0f, out _);
            Debug.Assert(clearPassed, "行動候補と評価結果の全削除", this);
            Check(clearPassed, "行動候補と評価結果の全削除");

            selector.TryAddOption(
                CreateOption("Disabled", 0f));

            bool zeroPassed =
                !selector.TrySelect(0f, out var zero) &&
                !zero.IsValid &&
                selector.LastEvaluations.Count == 1;
            Debug.Assert(zeroPassed, "評価値0の行動選択抑止", this);
            Check(zeroPassed, "評価値0の行動選択抑止");
        }

        /// <summary>
        /// 行動継続性と同点時の優先順位を検証する。
        /// </summary>
        private void TestContinuation()
        {
            var selector =
                new UtilitySelector<string, float>(0.1f);

            selector.TryAddOption(
                CreateOption("Patrol", 0.65f));

            selector.TryAddOption(
                CreateOption("Chase", 0.6f));

            bool continuePassed =
                selector.TrySelect(
                    0f, "Chase", out var continued) &&
                continued.ActionId == "Chase";
            Debug.Assert(continuePassed, "継続優遇による行動維持", this);
            Check(continuePassed, "継続優遇による行動維持");

            selector.SetContinuationBonus(0.01f);

            bool switchPassed =
                selector.TrySelect(
                    0f, "Chase", out var switched) &&
                switched.ActionId == "Patrol";
            Debug.Assert(switchPassed, "高評価行動への切り替え", this);
            Check(switchPassed, "高評価行動への切り替え");

            selector.Clear();
            selector.SetContinuationBonus(0f);

            selector.TryAddOption(
                CreateOption("First", 0.5f));

            selector.TryAddOption(
                CreateOption("Second", 0.5f));

            bool tiePassed =
                selector.TrySelect(0f, out var first) &&
                first.ActionId == "First";
            Debug.Assert(tiePassed, "同点時の登録順優先", this);
            Check(tiePassed, "同点時の登録順優先");

            bool currentTiePassed =
                selector.TrySelect(
                    0f, "Second", out var second) &&
                second.ActionId == "Second";
            Debug.Assert(currentTiePassed, "同点時の現在行動優先", this);
            Check(currentTiePassed, "同点時の現在行動優先");

            selector.Clear();
            selector.SetContinuationBonus(1f);

            selector.TryAddOption(
                CreateOption("Invalid", 0f));

            selector.TryAddOption(
                CreateOption("Valid", 0.1f));

            bool invalidPassed =
                selector.TrySelect(
                    0f, "Invalid", out var valid) &&
                valid.ActionId == "Valid";
            Debug.Assert(invalidPassed, "無効になった現在行動の解除", this);
            Check(invalidPassed, "無効になった現在行動の解除");
        }

        /// <summary>
        /// 不正入力と評価中の安全性を検証する。
        /// </summary>
        private void TestSafety()
        {
            bool rangePassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    UtilityMath.Normalize(0f, 1f, 1f);
                });
            Debug.Assert(rangePassed, "不正正規化範囲の拒否", this);
            Check(rangePassed, "不正正規化範囲の拒否");

            bool exponentPassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    UtilityMath.Power(0.5f, 0f);
                });
            Debug.Assert(exponentPassed, "不正指数の拒否", this);
            Check(exponentPassed, "不正指数の拒否");

            bool evaluatorPassed =
                Throws<ArgumentNullException>(() =>
                {
                    new UtilityConsideration<float>(
                        "Invalid", null);
                });
            Debug.Assert(evaluatorPassed, "null評価処理の拒否", this);
            Check(evaluatorPassed, "null評価処理の拒否");

            bool weightPassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    new UtilityOption<string, float>(
                        "Invalid",
                        Array.Empty<UtilityConsideration<float>>(),
                        1.1f);
                });
            Debug.Assert(weightPassed, "不正基本重みの拒否", this);
            Check(weightPassed, "不正基本重みの拒否");

            var selector =
                new UtilitySelector<string, float>();

            bool bonusPassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    selector.SetContinuationBonus(-1f);
                }) &&
                selector.ContinuationBonus == 0.1f;
            Debug.Assert(bonusPassed, "不正継続優遇値の拒否", this);
            Check(bonusPassed, "不正継続優遇値の拒否");

            selector.TryAddOption(
                new UtilityOption<string, float>(
                    "Reentrant",
                    new[]
                    {
                        new UtilityConsideration<float>(
                            "構成変更",
                            context =>
                            {
                                selector.Clear();

                                return 1f;
                            })
                    }));

            bool reentrantPassed =
                Throws<InvalidOperationException>(() =>
                {
                    selector.TrySelect(0f, out _);
                }) &&
                selector.Count == 1 &&
                selector.LastEvaluations.Count == 0;
            Debug.Assert(reentrantPassed, "評価中の構成変更防止", this);
            Check(reentrantPassed, "評価中の構成変更防止");

            selector.Clear();

            selector.TryAddOption(
                CreateOption("Recovered", 0.5f));

            bool recoveryPassed =
                selector.TrySelect(0f, out var recovered) &&
                recovered.ActionId == "Recovered";
            Debug.Assert(recoveryPassed, "例外発生後の再評価", this);
            Check(recoveryPassed, "例外発生後の再評価");
        }

        /// <summary>
        /// 指定された処理が期待する例外を発生させるか検証する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">検証対象の処理</param>
        /// <returns>期待する例外が発生した場合はtrue</returns>
        private bool Throws<TException>(Action action)
            where TException : Exception
        {
            try
            {
                action();
            }
            catch (Exception exception)
            {
                if (exception.GetType() == typeof(TException))
                {
                    return true;
                }

                throw;
            }

            return false;
        }

        /// <summary>
        /// 個別のテスト結果を出力し、結果を集計する。
        /// </summary>
        /// <param name="passed">テストの成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
